export function parseGraph(input) {
  const lines = input.split('\n')
  if (input.endsWith('\n')) lines.pop()

  const tasks = new Map()
  const depLines = []
  const references = []

  lines.forEach((rawLine, index) => {
    const lineNo = index + 1
    const trimmed = rawLine.trim()
    if (trimmed === '' || trimmed.startsWith('#')) return

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`line ${lineNo}: expected task <name> <cost>`)
      }
      const [, name, costText] = words
      if (!NAME_PATTERN.test(name)) {
        throw new CliError(`line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_PATTERN.test(costText)) {
        throw new CliError(`line ${lineNo}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new CliError(`line ${lineNo}: task ${name} is declared twice`)
      }
      tasks.set(name, { name, cost: parseInt(costText, 10), deps: [] })
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const [, name, ...deps] = words
      references.push(name, ...deps)
      depLines.push({ name, deps })
    } else {
      throw new CliError(`line ${lineNo}: unknown directive ${directive}`)
    }
  })

  for (const name of references) {
    if (!tasks.has(name)) {
      throw new CliError(`unknown task ${name}`)
    }
  }

  for (const { name, deps } of depLines) {
    const task = tasks.get(name)
    for (const dep of deps) {
      if (!task.deps.includes(dep)) task.deps.push(dep)
    }
  }

  return tasks
}
