 * Analysis over an already-parsed task map: cycle detection, per-task
 * start/finish/depth, and the priority used to pack tasks onto workers.
 */

import { CycleError } from './errors.js'

/**
 * Depth-first search from each task in ascending name order, walking each
 * task's dependencies in ascending name order. Throws a `CycleError` for the
 * first cycle such a search re-enters.
 */
export function detectCycle(tasks) {
  const names = [...tasks.keys()].sort()
  const state = new Map()
  const stack = []

  function visit(name) {
    state.set(name, 'active')
    stack.push(name)

    const deps = [...tasks.get(name).deps].sort()
    for (const dep of deps) {
      const depState = state.get(dep)
      if (depState === 'active') {
        const start = stack.indexOf(dep)
        throw new CycleError([...stack.slice(start), dep])
      }
      if (depState !== 'done') visit(dep)
    }

    stack.pop()
    state.set(name, 'done')
  }

  for (const name of names) {
    if (!state.has(name)) visit(name)
  }
}

/**
 * Start, finish and wave depth for every task, assuming an unlimited number
 * of workers.
 */
export function computeSchedule(tasks) {
  const result = new Map()

  function calc(name) {
    if (result.has(name)) return result.get(name)
    const task = tasks.get(name)
    let start = 0
    let depth = 0
    for (const dep of task.deps) {
      const depInfo = calc(dep)
      start = Math.max(start, depInfo.finish)
      depth = Math.max(depth, depInfo.depth + 1)
    }
    const info = { start, depth, finish: start + task.cost }
    result.set(name, info)
    return info
  }

  for (const name of tasks.keys()) calc(name)
  return result
}

/**
 * The cost of the longest chain starting at each task and running through
 * its dependents down to a task nothing depends on.
 */
export function computePriorities(tasks) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, task] of tasks) {
    for (const dep of task.deps) dependents.get(dep).push(name)
  }

  const result = new Map()

  function calc(name) {
    if (result.has(name)) return result.get(name)
    let best = 0
    for (const dependent of dependents.get(name)) {
      best = Math.max(best, calc(dependent))
    }
    const priority = tasks.get(name).cost + best
    result.set(name, priority)
    return priority
  }

  for (const name of tasks.keys()) calc(name)
  return result
}
"}

