 * Simulates running a task graph on a fixed number of workers, greedily
 * starting the highest-priority ready task on the lowest-index free worker.
 */

export function packSchedule(tasks, priorities, workerCount) {
  const remaining = new Set(tasks.keys())
  const finishOf = new Map()
  const freeAt = new Array(workerCount).fill(0)
  const logs = Array.from({ length: workerCount }, () => [])
  let time = 0

  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      let workerIndex = -1
      for (let i = 0; i < workerCount; i++) {
        if (freeAt[i] <= time) {
          workerIndex = i
          break
        }
      }
      if (workerIndex === -1) break

      let chosen = null
      for (const name of remaining) {
        const task = tasks.get(name)
        const ready = task.deps.every((dep) => finishOf.has(dep) && finishOf.get(dep) <= time)
        if (!ready) continue
        if (
          chosen === null ||
          priorities.get(name) > priorities.get(chosen) ||
          (priorities.get(name) === priorities.get(chosen) && name < chosen)
        ) {
          chosen = name
        }
      }
      if (chosen === null) break

      const task = tasks.get(chosen)
      const finish = time + task.cost
      logs[workerIndex].push({ name: chosen, start: time, finish })
      freeAt[workerIndex] = finish
      finishOf.set(chosen, finish)
      remaining.delete(chosen)
      progressed = true
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (freeAt[i] > time) next = Math.min(next, freeAt[i])
    }
    time = next
  }

  return logs
}
